4.  **Description of the Issue:** This function also suffers from the critical resource leak of not closing the iterator obtained from `GetStateByRange`. This can lead to resource exhaustion on the peer. Early returns due to errors during `Next()` also fail to close the iterator.
5.  **Recommended Fix:** Add `defer resultsIterator.Close()` immediately after the successful retrieval of the `resultsIterator`.

    ```go
    // DeactivateRange marks all assets in a range as inactive
    func (ar *AssetRegistryContract) DeactivateRange(ctx contractapi.TransactionContextInterface, startKey string, endKey string) (int, error) {
        resultsIterator, err := ctx.GetStub().GetStateByRange(startKey, endKey)
        if err != nil {
            return 0, err
        }
        // Add this line to ensure the iterator is closed
        defer resultsIterator.Close()

        count := 0
        for resultsIterator.HasNext() {
            queryResult, err := resultsIterator.Next()
            if err != nil {
                return count, err // Iterator will be closed by defer
            }

            var asset RegistryAsset
            json.Unmarshal(queryResult.Value, &asset)

            if asset.IsActive {
                asset.IsActive = false
                updatedJSON, _ := json.Marshal(asset)
                ctx.GetStub().PutState(asset.ID, updatedJSON)
                count++
            }
        }

        return count, nil
    }
